import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.x7b91k6X.js";const p=JSON.parse('{"title":"漫画 · 第 7 话 测试策略：XCTest 与质量门禁","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.07-testing-quality.md","filePath":"comics/EP.07-testing-quality.md","lastUpdated":1792677465000}'),r={name:"comics/EP.07-testing-quality.md"};function n(l,e,s,h,c,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="漫画-·-第-7-话-测试策略-xctest-与质量门禁" tabindex="-1">漫画 · 第 7 话 测试策略：XCTest 与质量门禁 <a class="header-anchor" href="#漫画-·-第-7-话-测试策略-xctest-与质量门禁" aria-label="Permalink to &quot;漫画 · 第 7 话 测试策略：XCTest 与质量门禁&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../07-testing-quality">07-testing-quality.md</a> ｜ 原画：<a href="./EP.07-testing-quality.svg">EP.07-testing-quality.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>斯威芙蒂</strong>：改了价格计算函数，手动点了下单页觉得没问题，结果线上购物车金额全错，退款工单 300+。</li><li><strong>Runtime 长老</strong>：教她搭测试金字塔，让 CI 在合并前就拦住坏代码。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>手动回归覆盖不全，公共函数一改，所有调用方都可能受影响。正确的解法是建立三层测试金字塔：底层大量快速的单元测试（70%）、中层集成测试（20%）、顶层少量端到端 UI 测试（10%）。每个单元测试遵循 Given-When-Then 三段式，CI 跑全量测试加覆盖率门禁，坏代码在 PR 阶段就被拦住。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>改了一个被多处调用的公共函数，手动只测了其中一个页面，其他调用方的边界条件全漏。线上爆发后才发现，损失已经造成。手动测试的根本问题是：<strong>覆盖范围依赖人的记忆力和耐心</strong>，代码量一大必然漏。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>测试金字塔（Mike Cohn 提出）：</p><ul><li><strong>单元测试（70%）</strong>：XCTest，测单个函数/类，mock 外部依赖，毫秒级执行。这是底座，量要大、速度要快。</li><li><strong>集成测试（20%）</strong>：测多模块协作，比如网络层 + 解析层 + 存储层的串联，需要真实数据库或测试服务器。</li><li><strong>UI 测试（10%）</strong>：XCUITest，端到端模拟用户操作，慢但最接近真实。只覆盖核心链路（登录、下单、支付）。</li></ul><p>比例倒过来（大量 UI 测试）会导致：跑一次半小时、随便改个 UI 就红一片、维护成本爆炸。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><ul><li><strong>Given-When-Then 三段式</strong>：Given 准备数据和 mock，When 执行被测操作，Then 断言结果。每个测试只验证一个行为。</li><li><strong>CI 门禁</strong>：PR 触发 <code>xcodebuild test</code>，全量测试必须通过；代码覆盖率低于阈值（如核心模块 80%）则禁止合并；SwiftLint 检查代码风格。</li><li><strong>Mock 依赖</strong>：网络请求用 <code>URLProtocol</code> mock 或依赖注入协议，不要让单元测试依赖真实网络。</li></ul><h2 id="runtime-长老划重点" tabindex="-1">Runtime 长老划重点 <a class="header-anchor" href="#runtime-长老划重点" aria-label="Permalink to &quot;Runtime 长老划重点&quot;">​</a></h2><ol><li>测试金字塔：单元 70% / 集成 20% / UI 10%，比例倒了又慢又脆。</li><li>Given-When-Then 三段式，每个测试只验证一个行为。</li><li>CI 跑全量测试 + 覆盖率门禁，坏代码在合并前就被拦住。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么不推荐写大量 UI 测试来替代单元测试？</p><p><strong>答</strong>：UI 测试有三个硬伤：①慢——启动 App + 模拟操作，一个用例几秒到几十秒，全量跑要半小时；②脆——UI 布局微调（改个控件 ID、挪个位置）就可能导致测试失败，但业务逻辑其实没坏；③难定位——UI 测试失败时堆栈指向 UI 操作，很难直接定位到是哪段业务逻辑出错。单元测试快、稳、定位准，所以金字塔底座必须是单元测试。UI 测试只用来守护最核心的端到端链路。</p><h2 id="去实验室" tabindex="-1">去实验室 <a class="header-anchor" href="#去实验室" aria-label="Permalink to &quot;去实验室&quot;">​</a></h2><p>运行 <code>swift test</code>，查看 <code>examples/Tests/GuideTests/</code> 下的 XCTest 和 Swift Testing 双框架示例；阅读第 7 章关于 XCUITest 录制与 <code>waitForExistence</code> 的部分。</p><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>测试体系建好了，该打包上架了。可签名证书、描述文件、公证……一堆名词绕晕人。第 8 话《构建部署：签名与 CI/CD》，把从源码到 App Store 的全链路跑通。</p>',24)])])}const g=t(r,[["render",n]]);export{p as __pageData,g as default};
